/* @lc app=leetcode id=3590 lang=kotlin */ class Solution { fun kthSmallest(par: IntArray, vals: IntArray, queries: Array<IntArray>): IntArray = par.size.let { n -> par.indices.drop(1).groupBy { par[it] }.let { g -> IntArray(n).let { px -> IntArray(n).let { tin -> IntArray(n).let { tout -> IntArray(n).let { ev -> IntArray(1).let { ct -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.forEach { e -> if (e >= 0) px.set(e, (if (e == 0) 0 else px[par[e]]) xor vals[e]).also { tin[e] = ct[0] }.also { ev[ct[0]] = px[e] }.also { ct[0]++ }.also { st.addFirst(e.inv()) }.also { g[e].orEmpty().forEach { c -> st.addFirst(c) } } else tout.set(e.inv(), ct[0] - 1) }.let { Math.max(1, Math.sqrt(n.toDouble()).toInt()).let { B -> IntArray(131072).let { cnt -> IntArray(256).let { bc -> queries.indices.sortedWith(compareBy<Int>({ tin[queries[it][0]] / B }, { if ((tin[queries[it][0]] / B) % 2 == 0) tout[queries[it][0]] else -tout[queries[it][0]] })).let { ord -> IntArray(queries.size).also { res -> ord.fold(0 to -1) { (cl, cr), qi -> tin[queries[qi][0]].let { l -> tout[queries[qi][0]].let { r -> (cl - 1 downTo l).forEach { i -> cnt.set(ev[i], cnt[ev[i]] + 1).let { if (cnt[ev[i]] == 1) bc[ev[i] / 512]++ } }.let { (cr + 1..r).forEach { i -> cnt.set(ev[i], cnt[ev[i]] + 1).let { if (cnt[ev[i]] == 1) bc[ev[i] / 512]++ } } }.let { (cl until l).forEach { i -> cnt.set(ev[i], cnt[ev[i]] - 1).let { if (cnt[ev[i]] == 0) bc[ev[i] / 512]-- } } }.let { (cr downTo r + 1).forEach { i -> cnt.set(ev[i], cnt[ev[i]] - 1).let { if (cnt[ev[i]] == 0) bc[ev[i] / 512]-- } } }.let { bc.runningFold(0) { a, b -> a + b }.let { cum -> cum.indexOfFirst { it >= queries[qi][1] }.let { bi -> res[qi] = if (bi < 0) -1 else (bi - 1).let { b -> (b * 512 until (b + 1) * 512).filter { cnt[it] > 0 }.elementAt(queries[qi][1] - cum[b] - 1) } } } }.let { l to r } } } } } } } } } } } } } } } } } } }